"""
    Adds markup around given text.
    Supports some colors by name instead of hexadecimal.

    :param text_str:
    :param color_str: (str) Hexadecimal color.
    :return: (str)
    """
def paint_text(text_str: Any, color_str: Any) -> object {
    return '[color={color_str}]{text_str}[/color]'.format(
        text_str=text_str, color_str=color_str
    );
}

